(function(){
  'use strict';
  const E=DairyEngine,L=DairyLevels,S=DairyStorage,A=DairyAcademy,Art=DairyArt,P=DairyProgress,MAX=L.levels.length;
  const state={data:S.load(),view:'home',level:null,queues:[],selected:null,hints:0,hintText:'',revealed:false,running:false,paused:false,result:null,guide:null,stuck:false,idleSeconds:0,instructionsOpen:false,academyCategory:"variables",example:0,lab:false,examAnswers:[null,null,null],examFeedback:null,examReady:false,modalBack:null};
  const app=document.getElementById('app');
  const icons={home:'⌂',levels:'▦',progress:'↗',concepts:'▤',settings:'⚙'};
  const navNames={home:'Mi fábrica',levels:'Misiones',progress:'Mi progreso',concepts:'Academia',settings:'Configuración'};
  const number=n=>new Intl.NumberFormat('es-CO').format(n);
  const stars=n=>`<span class="stars" aria-label="${n} de 3 estrellas">${'★'.repeat(n)}<span>${'☆'.repeat(3-n)}</span></span>`;
  function shell(content){
    const total=S.totals(state.data);
    app.innerHTML=`<aside class="sidebar"><a href="#" class="brand" data-nav="home"><span class="brand-mark">${Art.product("Leche fresca")}</span><span>La Vía Láctea<small>ESCUELA DE PRODUCCIÓN</small></span></a><span class="nav-label">TU CENTRO DE OPERACIONES</span><nav>${Object.keys(navNames).map(k=>`<button class="nav-item ${state.view===k?'active':''}" data-nav="${k}"><span>${icons[k]}</span>${navNames[k]}${k==='levels'?`<small>${MAX}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="rank-icon">✧</div><b>${total.completed===MAX?'Maestro de producción':total.completed>=8?'Jefe de producción':total.completed>=4?'Operador de planta':'Aprendiz de producción'}</b><small>${total.completed} de ${MAX} misiones completadas</small><div class="progress-track"><i style="width:${total.completed/MAX*100}%"></i></div><p>Una buena decisión cambia<br>todo el turno.</p></div><div class="sidebar-footer"><span class="live-dot"></span> Fábrica en línea <small>v2.0</small></div></aside><div class="workspace"><header class="topbar"><div><span class="breadcrumb">LA FÁBRICA</span><span class="breadcrumb-slash">/</span>${state.view==='game'?'Sala de producción':navNames[state.view]}</div><div class="top-status"><span title="Mejores puntos acumulados">✧ <b>${number(total.points)}</b> <span class="desktop-label">puntos</span></span><span class="star-total">★ <b>${total.stars}</b><span class="muted"> / ${MAX*3}</span></span><button class="icon-button" data-action="sound" aria-label="${state.data.settings.sound?'Silenciar':'Activar sonido'}" title="Sonido">${state.data.settings.sound?'♫':'♩'}</button><span class="avatar" title="Tu perfil local">JP</span></div></header><main id="main">${content}</main><footer class="page-footer"><span>HECHO PARA APRENDER JUGANDO</span><span>Planifica. Produce. Mejora.</span></footer></div>`;
    document.body.classList.toggle('reduce-motion',state.data.settings.reducedMotion);
  }
  function home(){
    const total=S.totals(state.data),next=L.levels.find(l=>!state.data.results[l.id])||L.levels[MAX-1];
    shell(`<section class="page-heading"><div><p class="eyebrow">UN NUEVO TURNO, NUEVAS POSIBILIDADES</p><h1>Tu fábrica. Tus decisiones.</h1><p>Convierte buenos pedidos en una gran producción.</p></div><div class="shift-pill"><span class="live-dot"></span> Turno de mañana <b>08:00</b></div></section><section class="home-hero"><div class="hero-copy"><span class="tag"><span>✦</span> ${total.completed?'TU SIGUIENTE DESAFÍO':'BIENVENIDO A LA PLANTA'}</span><h2>La receta está lista.<br>El orden lo pones tú.</h2><p>La leche acaba de llegar. Hay clientes esperando y una línea lista para arrancar. ¿Cómo organizarás tu primer turno?</p><button class="primary large" data-level="${next.id}">▶ ${total.completed?'Continuar campaña':'Comenzar mi primer turno'} <span>↗</span></button><div class="hero-caption"><span>◷</span> Misiones de 3–5 min <span>•</span> Aprende a tu ritmo</div></div><div class="hero-art"><img src="assets/factory.png" alt="Fábrica láctea isométrica con pasteurizadores, cinta de leche, trabajadores y camión de reparto"><div class="art-label"><span class="live-dot"></span> Todo listo para producir <span>✓</span></div></div></section><section class="home-stats"><div><span class="stat-icon sage">⚑</span><div><small>Misiones completadas</small><strong>${total.completed}<em> / ${MAX}</em></strong></div><span class="stat-note">Tu recorrido empieza aquí</span></div><div><span class="stat-icon gold">★</span><div><small>Estrellas obtenidas</small><strong>${total.stars}<em> / ${MAX*3}</em></strong></div><span class="stat-note">Siempre puedes mejorar</span></div><div><span class="stat-icon blue">✧</span><div><small>Puntaje acumulado</small><strong>${number(total.points)}</strong></div><span class="stat-note">Cada decisión suma</span></div></section><section class="section-title"><div><p class="eyebrow">DE APRENDIZ A JEFE DE PLANTA</p><h2>Tu camino por la fábrica</h2></div><button class="text-button" data-nav="levels">Ver las ${MAX} misiones <span>→</span></button></section><section class="world-grid">${L.worlds.map(w=>worldCard(w)).join('')}</section><section class="home-living"><div><p class="eyebrow">DE LA GRANJA AL CLIENTE</p><h2>Cada estación cuenta.</h2><p>Recibe, organiza y despacha. Detrás de cada buen turno hay una buena decisión.</p><button class="text-button" data-nav="concepts">Entrar a la Academia →</button></div>${Art.scene()}</section><div class="tip-strip"><span>💡</span><p><b>El secreto de una buena producción</b> no siempre es trabajar más rápido. A veces, basta con elegir qué va primero.</p><button class="text-button" data-nav="concepts">Explorar conceptos →</button></div>`);
  }
  function worldArt(id){return id===1?Art.product('Leche fresca'):id===2?Art.machine():id===3?Art.truck():Art.medal();}
  function worldCard(w){const done=w.ids.filter(id=>state.data.results[id]).length,unlocked=S.isUnlocked(state.data,w.ids[0]);return `<button class="world-card ${w.color} ${unlocked?'':'locked'}" data-world="${w.id}" aria-label="Ver mundo ${w.id}: ${w.name}"><div class="world-card-top"><span class="world-icon">${worldArt(w.id)}</span><span class="world-status">${done===w.ids.length?'✓ COMPLETADO':unlocked?'DISPONIBLE':'▣ BLOQUEADO'}</span></div><span class="eyebrow">MUNDO 0${w.id} · ${w.place.toUpperCase()}</span><h3>${w.name}</h3><p>${w.description}</p><div class="world-card-bottom"><span>${done} / ${w.ids.length} misiones</span><span>${unlocked?'→':'Completa el mundo anterior'}</span></div><div class="world-dots">${w.ids.map(id=>`<i class="${state.data.results[id]?'filled':''}"></i>`).join('')}</div></button>`;}
  const time=(minutes)=>{const t=480+Math.floor(minutes);return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;};
  const machineName=m=>'Pasteurizador '+String.fromCharCode(65+m);
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let toastTimer,dragged=null,previousFocus=null,guideTimer;
  function resetIdle(){state.idleSeconds=0;state.stuck=false;const panel=document.getElementById('stuck-help');if(panel)panel.hidden=true;}
  setInterval(()=>{if(state.view!=='game'||state.running||state.guide||document.hidden||document.getElementById('modal').open)return;if(++state.idleSeconds>=45&&!state.stuck){state.stuck=true;const panel=document.getElementById('stuck-help');if(panel)panel.hidden=false;document.getElementById('announcer').textContent='Si te atascaste, puedes pedir una pista o ver una explicación paso a paso. No hay límite de tiempo.';}},1000);
  function learningPanel(schedule){
    const g=state.guide;
    if(g){
      const o=g.operations[g.index-1];let explanation='Vamos a recorrer un plan completo óptimo. Sus decisiones funcionan en conjunto; puede haber otros planes igual de buenos. Avanza a tu ritmo o reproduce la explicación. Tu plan original está guardado.';
      if(o){const prev=g.operations.filter(x=>x.machine===o.machine&&x.end<=o.start&&x.id!==o.id).sort((a,b)=>b.end-a.end)[0],free=prev?.end||0,ready=Math.max(free,o.r);explanation=`Colocamos ${o.id} (${o.product}) en la línea ${String.fromCharCode(65+o.machine)}: ${time(o.start)}–${time(o.end)}. `;if(o.r>free)explanation+=`La máquina espera ${o.r-free} min por su disponibilidad a las ${time(o.r)}. `;if(o.start>ready)explanation+=`Desde las ${time(ready)} no cabe un proceso continuo de ${o.p} min antes de la pausa; se mueve a las ${time(o.start)}. `;if(o.start===ready&&o.r<=free)explanation+=`Empieza ${prev?'cuando termina '+prev.id:'al abrir el turno'}, sin espera adicional. `;if(state.level.show.includes('d'))explanation+=o.T?`Termina ${o.T} min tarde${state.level.show.includes('w')?'; con peso '+o.w+' aporta '+o.T*o.w+' al retraso ponderado':''}. `:'Cumple la entrega prometida. ';const contributions={'makespan':`El último pedido del plan completo termina a las ${time(g.benchmark.schedule.metrics.cmax)}.`, 'total-completion-time':`Este pedido aporta Cj = ${o.C} min a la suma de finalizaciones.`, 'weighted-completion':`Su aporte ponderado es ${o.w} × ${o.C} = ${o.w*o.C}.`, 'total-tardiness':`Aporta ${o.T} min al retraso total. Terminar antes no resta el retraso de otro pedido.`, 'weighted-tardiness':`Su retraso ponderado es ${o.w} × ${o.T} = ${o.w*o.T}.`, 'late-jobs':o.T?'Este pedido suma 1 al número de entregas tardías.':'Este pedido no suma entregas tardías.', 'load-balance':`Añade ${o.p} min de carga a esta máquina; las esperas y pausas no cuentan como trabajo.`};explanation+=contributions[state.level.objective];}
      return `<section class="learning-guide" aria-label="Respuesta guiada"><div class="guide-header"><span class="mentor">👩‍🏭</span><div><p class="eyebrow">APRENDER CON LUCÍA · PASO ${g.index} / ${g.operations.length}</p><h2>${o?o.id+' · '+o.product:'Vamos a resolverlo juntos'}</h2></div><span class="tag">PRÁCTICA</span></div><p class="guide-explanation" aria-live="polite">${explanation}</p><div class="guide-timeline">${gantt(schedule)}</div>${g.index===g.operations.length?`<div class="guide-conclusion"><b>La secuencia completa alcanza ${g.benchmark.value} ${E.OBJECTIVES[state.level.objective].unit} en ${E.OBJECTIVES[state.level.objective].symbol}.</b><p>${state.level.lesson}</p></div>`:''}<div class="guide-buttons"><button class="secondary" data-action="guide-back" ${g.index===0?'disabled':''}>← Anterior</button><button class="primary" data-action="guide-next" ${g.index===g.operations.length?'disabled':''}>Siguiente paso →</button><button class="secondary" data-action="guide-play" ${g.index===g.operations.length?'disabled':''}>${g.playing?'Ⅱ Pausar explicación':'▶ Reproducir pasos'}</button><button class="text-button" data-action="guide-restore">Volver a mi plan</button><button class="text-button" data-action="retry">Ahora me toca · empezar de nuevo</button></div><small>Observa cómo cambia la cola y el Gantt debajo. La demostración no modifica tus récords.</small></section>`;
    }
    return `<div id="stuck-help" class="stuck-help" ${state.stuck?'':'hidden'}><span>💡</span><div><b>¿Necesitas otra forma de verlo?</b><p>No hay límite de tiempo. Puedes pedir una pista o construir la respuesta con Lucía, paso a paso.</p></div><button class="secondary" data-action="hint" ${state.hints>=3?'disabled':''}>Una pista</button><button class="primary" data-action="guide-start">Ver paso a paso</button><button class="icon-button" data-action="dismiss-help" aria-label="Cerrar sugerencia de ayuda">×</button></div><details class="quick-instructions" ${state.instructionsOpen?'open':''}><summary>Cómo jugar esta misión</summary><ol><li><b>Lee la misión.</b> ${E.OBJECTIVES[state.level.objective].label}: un valor menor es mejor.</li><li><b>Elige un pedido.</b> Arrastra su tarjeta a una cola, o selecciónala y pulsa «Colocar aquí». ${state.level.machines>1?'Elige también la máquina.':''}</li><li><b>Ajusta el orden.</b> Arrastra antes de otro pedido, usa las flechas ‹ › o selecciona y pulsa un +. × devuelve el pedido a pendientes.</li><li><b>Mira el Gantt.</b> Los huecos son espera; las franjas con ☕ son descansos. Pulsa un bloque para ver sus tiempos.</li><li><b>Inicia producción</b> cuando todos estén en cola. Obtendrás una explicación y podrás reintentar. Si necesitas ayuda, pide una pista o una respuesta guiada.</li></ol></details>`;
  }
  function beginGuide(){if(state.running||state.guide)return;resetIdle();const benchmark=E.solveLevel(state.level);state.guide={snapshot:state.queues.map(q=>[...q]),selection:state.selected,operations:[...benchmark.schedule.operations].sort((a,b)=>a.start-b.start||a.machine-b.machine||a.id.localeCompare(b.id)),benchmark,index:0,playing:false};state.queues=state.queues.map(()=>[]);state.selected=null;state.result=null;state.revealed=true;render();document.querySelector('.learning-guide').scrollIntoView({block:'start',behavior:state.data.settings.reducedMotion?'instant':'smooth'});}
  function guideStep(delta){const g=state.guide;if(!g)return;g.index=Math.max(0,Math.min(g.operations.length,g.index+delta));state.queues=Array.from({length:state.level.machines},()=>[]);g.operations.slice(0,g.index).forEach(o=>state.queues[o.machine].push(o.id));if(g.index===g.operations.length){g.playing=false;clearTimeout(guideTimer);}render();document.querySelector('[data-action="guide-next"]')?.focus({preventScroll:true});}
  function playGuide(){const g=state.guide;if(!g)return;g.playing=!g.playing;clearTimeout(guideTimer);render();function next(){if(!state.guide?.playing)return;if(document.hidden||document.getElementById('modal').open){guideTimer=setTimeout(next,1000);return;}guideStep(1);if(state.guide?.playing)guideTimer=setTimeout(next,5500);}if(g.playing)guideTimer=setTimeout(next,700);}
  function restoreGuide(){const g=state.guide;if(!g)return;clearTimeout(guideTimer);simulation.stop();state.running=false;state.queues=g.snapshot;state.selected=g.selection;state.guide=null;resetIdle();render();toast('Tu plan original está restaurado. Reintenta para registrar un nuevo récord.');}
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);document.getElementById('announcer').textContent=message;}
  function modal(content){const d=document.getElementById('modal');previousFocus=document.activeElement;d.innerHTML=content;if(!d.open)d.showModal();}
  function closeModal(){const d=document.getElementById('modal');if(state.modalBack){d.innerHTML=state.modalBack;state.modalBack=null;d.querySelector('button')?.focus();return;}d.close();previousFocus?.focus?.();}
  function title(eyebrow,heading,copy){return `<section class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1>${copy?`<p>${copy}</p>`:''}</div></section>`;}
  function levelMap(){
    shell(title(MAX+' MISIONES · UNA FÁBRICA POR DESCUBRIR','Un turno a la vez.','Completa una misión para desbloquear la siguiente. Una estrella es suficiente.')+L.worlds.map(w=>`<section class="chapter ${w.color}" id="world-${w.id}"><div class="chapter-heading"><span class="station-art">${worldArt(w.id)}</span><div><p class="eyebrow">MUNDO 0${w.id} · ${w.place.toUpperCase()}</p><h2>${w.name}</h2></div><span>${w.ids.filter(id=>state.data.results[id]).length} / ${w.ids.length} completadas</span></div><div class="level-grid">${w.ids.map(id=>{const l=L.levels[id-1],r=state.data.results[id],unlocked=S.isUnlocked(state.data,id);return `<button class="level-card ${unlocked?'':'locked'}" data-level="${id}" ${unlocked?'':`disabled title="Completa la misión ${id-1} para desbloquear"`}><div><span class="level-number">${String(id).padStart(2,'0')}</span><span class="level-product">${Art.product(l.jobs[0].product)}</span><span class="level-tag">${unlocked?l.tag:'▣ Por desbloquear'}</span></div><h3>${l.title}</h3><p>${l.jobs.length} pedidos · ${l.machines} ${l.machines===1?'máquina':'máquinas'}</p><div class="level-bottom">${stars(r?.stars||0)}<span>${r?number(r.points)+' pts':unlocked?'Jugar →':'Completa la misión '+(id-1)}</span></div></button>`;}).join('')}</div></section>`)+`<div class="note-box"><b>La fábrica puede seguir creciendo.</b><p>Esta campaña cubre una máquina y máquinas paralelas. Flow Shop, Job Shop, eventos y habilidades quedan para la siguiente expansión.</p></div>`);
  }
  function progress(){
    const total=S.totals(state.data);
    const medals=P.achievements.map(a=>[Art.medal(),a.name,a.earned(state.data),a.description]);
    shell(title('CADA INTENTO TE ENSEÑA ALGO','Tu trayectoria en la planta','Se guarda tu mejor puntaje, tus mejores estrellas y el menor objetivo de cada misión.')+`<div class="progress-summary"><div><strong>${number(total.points)}</strong><span>Puntos acumulados</span></div><div><strong>${total.stars}<em> / ${MAX*3}</em></strong><span>Estrellas obtenidas</span></div><div><strong>${total.completed}<em> / ${MAX}</em></strong><span>Misiones completadas</span></div></div><div class="medals">${medals.map(([icon,name,earned,desc])=>`<div class="medal ${earned?'earned':''}"><span>${icon}</span><b>${name}</b><small>${earned?'✓ '+desc:desc}</small></div>`).join('')}</div><section class="panel"><div class="panel-heading"><h2>Tu libro de turnos</h2><span>Los reintentos no duplican puntos</span></div><div class="table-scroll"><table><thead><tr><th>Misión</th><th>Estrellas</th><th>Mejor objetivo</th><th>Puntos</th><th>Intentos</th><th></th></tr></thead><tbody>${L.levels.map(l=>{const r=state.data.results[l.id];return `<tr><td><b>${String(l.id).padStart(2,'0')} · ${l.title}</b></td><td>${stars(r?.stars||0)}</td><td>${r?`${r.bestObjective} <small>${E.OBJECTIVES[l.objective].unit}</small>`:'—'}</td><td>${r?number(r.points):'—'}</td><td>${r?.attempts||'—'}</td><td><button class="text-button" data-level="${l.id}" ${S.isUnlocked(state.data,l.id)?'':'disabled'}>${r?'Reintentar':'Jugar'} →</button></td></tr>`;}).join('')}</tbody></table></div></section>`);
  }
  function concepts(){shell((state.level?'<button class="secondary return-turn" data-action="return-turn">← Volver a mi turno · '+state.level.title+'</button>':'')+DairyAcademyUI.render(state.data,state.academyCategory,state.example,state.lab));}
  function openConcept(id){const before=P.achievements.filter(a=>a.earned(state.data)).map(a=>a.id);if(!P.visit(state.data,id))return;const dialog=document.getElementById('modal');if(dialog.open&&dialog.querySelector('.result-hero'))state.modalBack=dialog.innerHTML;modal(DairyAcademyUI.concept(id));if(state.view==='concepts')concepts();const fresh=P.achievements.filter(a=>a.earned(state.data)&&!before.includes(a.id));if(fresh.length)toast('Logro: '+fresh.map(a=>a.name).join(', '));}
  function examIntro(){shell(DairyAcademyUI.exam(state.level,state.examAnswers,state.examFeedback));}
  function formalTable(l){return '<section class="panel academic-orders"><h2>Orden de dirección · '+l.notation+'</h2><p>Todos los tiempos son minutos desde las 08:00.</p><div class="table-scroll"><table><thead><tr><th>Job</th><th>pj</th><th>rj</th><th>dj</th><th>wj</th></tr></thead><tbody>'+l.jobs.map(j=>'<tr><td>'+j.id+' · '+j.product+'</td><td>'+j.p+'</td><td>'+j.r+'</td><td>'+j.d+'</td><td>'+j.w+'</td></tr>').join('')+'</tbody></table></div></section>';}
  function floor(l){return '<section class="factory-floor"><div class="floor-label"><p class="eyebrow">LA PLANTA EN VIVO</p><b id="floor-state">Lista para tu plan</b></div><div class="floor-machines">'+Array.from({length:l.machines},(_,m)=>'<div class="floor-machine" data-live-machine="'+m+'">'+Art.machine(m)+'<span>Línea '+String.fromCharCode(65+m)+'</span></div>').join('')+'</div><div class="dispatch"><div class="dispatch-products">'+l.jobs.map(j=>'<span data-dispatch="'+j.id+'" hidden>'+Art.product(j.product)+'<b>'+j.id+' ✓</b></span>').join('')+'</div>'+Art.truck()+'<span>Zona de despacho</span></div></section>';}

  function settings(){shell(title('A TU RITMO','Configuración','Tus preferencias se guardan en este navegador.')+`<section class="panel settings-panel"><label class="setting-row"><span><b>Sonidos de la fábrica</b><small>Pedidos, entregas y final del turno.</small></span><input type="checkbox" data-setting="sound" ${state.data.settings.sound?'checked':''}></label><label class="setting-row"><span><b>Reducir movimiento</b><small>Desactiva transiciones y movimiento decorativo.</small></span><input type="checkbox" data-setting="reducedMotion" ${state.data.settings.reducedMotion?'checked':''}></label><label class="setting-row"><span><b>Velocidad de simulación</b><small>Solo cambia la animación; los minutos de producción son los mismos.</small></span><select data-setting="speed" aria-label="Velocidad de simulación">${[1,2,4].map(n=>`<option value="${n}" ${state.data.settings.speed===n?'selected':''}>${n}×</option>`).join('')}</select></label><div class="setting-row"><span><b>Progreso local</b><small>${S.available?'Guardado en este navegador. No requiere cuenta.':'El almacenamiento no está disponible. El progreso durará esta sesión.'}</small></span><button class="secondary danger" data-action="reset-dialog">Reiniciar progreso</button></div></section>`);}
  function startLevel(id){
    const level=L.levels.find(l=>l.id===Number(id));if(!level||!S.isUnlocked(state.data,level.id)){toast('Completa la misión anterior para desbloquear esta zona.');return false;}
    simulation.stop();clearTimeout(guideTimer);state.guide=null;resetIdle();state.instructionsOpen=false;state.modalBack=null;closeModal();state.level=level;state.view='game';state.queues=Array.from({length:level.machines},()=>[]);state.selected=null;state.hints=0;state.hintText='';state.revealed=false;state.running=false;state.paused=false;state.result=null;state.data.lastLevel=level.id;state.examAnswers=[null,null,null];state.examFeedback=null;state.examReady=!level.formal;P.discover(state.data,level.id);S.save(state.data);render();window.scrollTo(0,0);return true;
  }
  function currentSchedule(){return E.calculateSchedule(state.level,state.queues);}
  function jobCard(j,schedule){
    const placed=state.queues.some(q=>q.includes(j.id)),o=schedule.operations.find(o=>o.id===j.id),selected=state.selected===j.id;
    return `<button class="job-card ${placed?'placed':''} ${selected?'selected':''}" style="--job-color:${j.color}" draggable="false" data-job="${j.id}" aria-pressed="${selected}" aria-label="${j.id}, ${j.product}, ${j.p} minutos${placed?', asignado':''}. Seleccionar pedido." ${state.running?'disabled':''}><span class="job-top"><span class="job-icon">${Art.product(j.product)}</span><span class="job-id">${j.id}</span><span class="drag-handle" aria-hidden="true">⠿</span></span><b>${j.product}</b><small class="client">${j.client}</small><span class="job-duration" title="Tiempo de procesamiento — pj"><small>Tarda</small> <b>${j.p}</b> min <span class="info-dot" aria-label="Tiempo de procesamiento pj">ⓘ</span></span><span class="job-details">${state.level.show.includes('r')?`<span title="Momento de disponibilidad — rj">Disponible desde <b>${time(j.r)}</b></span>`:''}${state.level.show.includes('d')?`<span title="Hora prometida de entrega — dj">Entrega <b>${time(j.d)}</b></span>`:''}${state.level.show.includes('w')?`<span title="Importancia del pedido — wj. No son estrellas de rendimiento.">Prioridad ⓘ <b>${j.w>=4?'Alta':j.w>=2?'Media':'Normal'} <small>×${j.w}</small></b></span>`:''}</span><span class="order-status" data-order-status="${j.id}"></span><span class="job-placement">${placed?`✓ Línea ${String.fromCharCode(65+o.machine)}`:selected?'Seleccionado · elige una posición':'Arrastra o selecciona'}</span></button>`;
  }
  function queueMarkup(queue,m){return `<div class="machine-queue"><div class="machine-header"><span class="machine-badge">${Art.machine(m)}</span><div><b>${machineName(m)}</b><small>${state.level.machines>1?'Máquina idéntica · ':''}${queue.reduce((n,id)=>n+state.level.jobs.find(j=>j.id===id).p,0)} min de carga</small></div><span class="machine-status" id="machine-status-${m}">● En espera</span></div><div class="queue-row" data-drop-machine="${m}" data-drop-index="${queue.length}">${queue.length?queue.map((id,i)=>{const j=state.level.jobs.find(j=>j.id===id);return `<button class="insert-point" data-place-machine="${m}" data-place-index="${i}" data-drop-machine="${m}" data-drop-index="${i}" aria-label="Insertar pedido seleccionado antes de ${id}" ${!state.selected||state.running?'disabled':''}>+</button><div class="queue-job ${state.selected===id?'selected':''}" style="--job-color:${j.color}" data-drag-job="${id}" data-drop-machine="${m}" data-drop-index="${i}" draggable="false"><button class="queue-select" data-job="${id}" aria-label="Seleccionar ${id} en la cola" ${state.running?'disabled':''}><span class="queue-product">${Art.product(j.product)}</span><b>${id}</b><small>${j.p} min</small></button><div class="queue-tools"><button data-move="${id}" data-direction="-1" aria-label="Mover ${id} a la izquierda" ${i===0||state.running?'disabled':''}>‹</button><button data-remove="${id}" aria-label="Retirar ${id}" ${state.running?'disabled':''}>×</button><button data-move="${id}" data-direction="1" aria-label="Mover ${id} a la derecha" ${i===queue.length-1||state.running?'disabled':''}>›</button></div></div>`;}).join(''):''}<button class="queue-add ${queue.length?'compact':''}" data-place-machine="${m}" data-place-index="${queue.length}" data-drop-machine="${m}" data-drop-index="${queue.length}" ${state.running?'disabled':''}><span>＋</span>${queue.length?'Añadir':state.selected?'Colocar '+state.selected+' aquí':'Arrastra un pedido aquí'}<small>${queue.length?'':'o selecciona una tarjeta y pulsa aquí'}</small></button></div></div>`;}
  function gantt(schedule){
    const level=state.level,totalP=level.jobs.reduce((s,j)=>s+j.p,0),maxBreak=Math.max(0,...level.breaks.map(b=>b.end));
    const horizon=Math.ceil(Math.max(60,schedule.metrics.cmax,totalP/level.machines,maxBreak)/30)*30;
    const step=horizon>240?60:30;let labels='';for(let t=0;t<=horizon;t+=step)labels+=`<span style="left:${t/horizon*100}%">${time(t)}</span>`;
    const rows=Array.from({length:level.machines},(_,m)=>`<div class="gantt-row"><div class="gantt-label">Línea ${String.fromCharCode(65+m)}</div><div class="gantt-track" data-horizon="${horizon}">${level.breaks.filter(b=>b.machine==null||b.machine===m).map(b=>`<div class="gantt-break" style="left:${b.start/horizon*100}%;width:${(b.end-b.start)/horizon*100}%" title="${b.label}: ${time(b.start)}–${time(b.end)}"><span>☕</span></div>`).join('')}${schedule.operations.filter(o=>o.machine===m).map(o=>`<button class="gantt-block ${o.p/horizon<.09?'compact':''} ${level.show.includes('d')&&o.T>0?'late':''}" style="left:${o.start/horizon*100}%;width:${o.p/horizon*100}%;--job-color:${o.color}" data-inspect="${o.id}" data-operation="${o.id}" title="${o.id} · ${o.product} · Inicio ${time(o.start)} · Fin ${time(o.end)} · Duración ${o.p} min · Entrega ${time(o.d)} · Retraso ${o.T} min${level.show.includes('d')?`, ${o.T?'tarde '+o.T+' min':'a tiempo'}`:''}" aria-label="Detalles ${o.id}, ${o.product}, ${time(o.start)} a ${time(o.end)}"><span class="gantt-product">${Art.product(o.product)}</span><span>${o.id}</span><small>${o.p}′</small><i class="block-progress"></i></button>`).join('')}<div class="playhead" style="display:none"></div></div></div>`).join('');
    return `<div class="gantt-scroll"><div class="gantt-chart"><div class="gantt-axis"><div>${labels}</div></div>${rows}</div></div>`;
  }
  function tutorial(schedule){
    if(state.level.id!==1||state.guide)return '';
    const count=schedule.metrics.completed;
    const text=count===0?'Selecciona o arrastra una tarjeta. Colócala en la cola de la máquina.':count<3?'¡Bien! Cada tarjeta ocupa la máquina los minutos indicados. Coloca los pedidos que faltan.':'Los tres pedidos están listos. Pulsa Iniciar producción y observa cómo avanza el turno.';
    return `<div class="tutorial"><span class="mentor">👩‍🏭</span><div><b>Lucía · Jefa de planta</b><p>${text}</p></div><span class="step-indicator">${Math.min(3,count+1)} / 3</span></div>`;
  }
  function game(){
    const l=state.level;if(l.formal&&!state.examReady){examIntro();return;}const schedule=currentSchedule(),o=E.OBJECTIVES[l.objective];
    shell(`<section class="game-heading"><button class="back-button" data-nav="levels" aria-label="Volver a misiones">←</button><div><p class="eyebrow">MUNDO 0${l.world} · MISIÓN ${String(l.id).padStart(2,'0')} / ${MAX}</p><h1>${l.title}</h1></div><div class="game-heading-end"><span class="tag">${l.id===12?'Maestría':l.tag}</span>${stars(state.data.results[l.id]?.stars||0)}</div></section><div class="mission-banner"><span>⚑</span><div><p>${l.mission}</p><small>🎯 ${l.formal?l.notation:A.goals[l.objective][0]}</small><button class="concept-link" data-concept="${l.objective}">📘 Concepto relacionado: ${A.goals[l.objective][1]} ⓘ</button></div></div>${floor(l)}${l.formal?formalTable(l):''}${tutorial(schedule)}${learningPanel(schedule)}<div class="game-layout"><div class="planning-area"><section class="panel orders-panel"><div class="panel-heading"><div><h2>Pedidos del turno <span class="count-badge">${l.jobs.length}</span></h2><p>Selecciona, coloca y prueba otro orden.</p></div><span class="placed-count">${schedule.metrics.completed} / ${l.jobs.length} en cola</span></div><div class="jobs-grid">${l.jobs.map(j=>jobCard(j,schedule)).join('')}</div></section><section class="panel queue-panel"><div class="panel-heading"><div><h2>Líneas de producción</h2><p>${state.selected?`<b>${state.selected}</b> seleccionado. Pulsa + para elegir su posición.`:'Arrastra para ordenar. Usa las flechas para ajustar.'}</p></div><button class="text-button" data-action="clear" ${state.running?'disabled':''}>↺ Vaciar</button></div>${state.queues.map((q,m)=>queueMarkup(q,m)).join('')}</section><section class="panel timeline-panel"><div class="panel-heading"><div><h2>Tu plan, minuto a minuto</h2><p>Haz clic en un bloque para ver los tiempos del pedido.</p></div><span id="simulation-clock" class="clock-display">${time(0)}</span></div>${gantt(schedule)}<div class="gantt-legend"><span>■ Producción</span><span class="legend-idle">▱ Espera</span>${l.breaks.length?'<span>☕ Descanso obligatorio</span>':''}${l.show.includes('d')?'<span class="legend-late">! Borde rojo: entrega tardía</span>':''}</div>${l.breaks.length?`<p class="break-note">${l.breaks.map(b=>`${b.label}${b.machine==null?' · todas las líneas':''}: ${time(b.start)}–${time(b.end)}`).join(' · ')}</p>`:''}</section></div><aside class="mission-aside"><section class="panel live-metrics"><p class="eyebrow">PREVISIÓN DEL TURNO</p><div class="objective-value"><span>${l.formal?o.symbol:'TU META'}</span><strong>${schedule.operations.length?schedule.objective:'—'}</strong><small>${o.unit}</small></div><p class="objective-caption">${A.goals[l.objective][1]} · menos es mejor</p><div class="metric-row"><span>Fin de producción</span><b>${schedule.operations.length?time(schedule.metrics.cmax):'—'}</b></div>${l.show.includes('d')?`<div class="metric-row"><span>Entregas a tiempo</span><b class="${schedule.metrics.lateCount?'risk':'good'}">${schedule.metrics.onTime} / ${schedule.metrics.completed}</b></div><div class="metric-row"><span>Retraso total</span><b>${schedule.metrics.totalTardiness} min</b></div>`:''}<div class="metric-row"><span>Tiempo ocioso</span><b>${schedule.metrics.idle} min</b></div><div class="metric-row"><span>Utilización</span><b>${Math.round(schedule.metrics.utilization*100)}%</b></div><p class="small-note">${schedule.complete?'Plan completo. Listo para simular.':'Previsión parcial: coloca todos los pedidos.'}</p><div class="production-controls">${state.running?`<button class="primary" data-action="pause">${state.paused?'▶ Reanudar':'Ⅱ Pausar'}</button><button class="secondary" data-action="finish">Ver resultado</button><button class="text-button" data-action="cancel-simulation">Detener y editar</button>`:`<button class="primary" data-action="start" ${schedule.complete?'':'disabled'}>▶ Iniciar producción</button>`}</div><label class="speed-control">Velocidad <select data-setting="speed" aria-label="Velocidad de simulación">${[1,2,4].map(n=>`<option value="${n}" ${state.data.settings.speed===n?'selected':''}>${n}×</option>`).join('')}</select></label>${state.revealed?'<p class="practice-note">Modo práctica: solución consultada. Sin nuevos puntos ni desbloqueos.</p>':''}</section><section class="hint-panel"><span class="hint-icon">✧</span><h3>Una pequeña ayuda</h3><p>${state.hintText||'A veces solo necesitas mirar el problema desde otro ángulo.'}</p><button class="secondary" data-action="hint" ${state.hints>=3||state.running?'disabled':''}>${state.hints>=3?'Todas las pistas vistas':'Ver pista '+(state.hints+1)+' de 3'}</button><small>Cada pista resta 100 puntos.<br>Las estrellas no cambian.</small><button class="guided-answer" data-action="guide-start" ${state.running||state.guide?'disabled':''}>▷ Ver respuesta paso a paso</button><small>Una demostración explicada, a tu ritmo.</small></section><div class="rule-note"><span>✓</span><p>La máquina respeta llegadas y descansos automáticamente. Tu decisión es el orden${l.machines>1?' y la asignación':''}.</p></div></aside></div>`);
  }
  function moveJob(id,m,index){
    if(state.guide)return false;resetIdle();
    if(state.running||!state.level.jobs.some(j=>j.id===id)||!Number.isInteger(m)||m<0||m>=state.queues.length)return false;
    if(!Number.isInteger(index)||index<0||index>state.queues[m].length)return false;
    const oldMachine=state.queues.findIndex(q=>q.includes(id)),oldIndex=oldMachine<0?-1:state.queues[oldMachine].indexOf(id);
    if(oldMachine===m&&oldIndex<index)index--;
    state.queues=state.queues.map(q=>q.filter(x=>x!==id));state.queues[m].splice(index,0,id);state.selected=null;state.result=null;
    DairySimulation.tone('place',state.data.settings.sound);render();document.getElementById('announcer').textContent=`${id} colocado en ${machineName(m)}, posición ${index+1}.`;return true;
  }
  function removeJob(id){if(state.running||state.guide)return;resetIdle();state.queues=state.queues.map(q=>q.filter(x=>x!==id));state.selected=null;state.result=null;render();}
  function hint(){if(state.hints>=3||state.running)return;resetIdle();state.hintText=state.level.hints[state.hints++].replace('Las estrellas representan importancia','La prioridad indica importancia');render();document.getElementById('announcer').textContent=state.hintText;}
  function inspectJob(id){const o=currentSchedule().operations.find(o=>o.id===id);if(!o)return;modal(`<div class="dialog-heading"><span class="inspect-art">${Art.product(o.product)}</span><button class="icon-button" data-action="close" aria-label="Cerrar">×</button></div><p class="eyebrow">PEDIDO ${o.id} · ${machineName(o.machine).toUpperCase()}</p><h2 id="dialog-title">${o.product}</h2><p class="dialog-intro">${time(o.start)} → ${time(o.end)} · ${o.p} min de proceso</p><div class="job-metrics"><div>Inicio <b>${o.start} min</b></div><div>Hora de finalización <b>${o.C} min</b></div><div>Tiempo dentro del sistema <b>${o.F} min</b></div><div>Diferencia frente a la promesa <b>${o.L} min</b></div><div>Tiempo de retraso <b>${o.T} min</b></div><div>Finalización por importancia <b>${o.w*o.C}</b></div><div>Retraso por importancia <b>${o.w*o.T}</b></div></div><p class="dialog-intro">Disponible ${time(o.r)} · entrega ${time(o.d)} · prioridad ${o.w}. Todos los valores se miden desde las 08:00.</p><button class="primary" data-action="close">Entendido</button>`);}
  function productionTick(t,schedule){
    const clock=document.getElementById('simulation-clock');if(!clock)return;clock.textContent=time(t);const floorState=document.getElementById('floor-state');if(floorState)floorState.textContent='Turno en marcha · '+time(t);
    schedule.operations.forEach(o=>{const done=t>=o.end,live=document.querySelector('[data-order-status="'+o.id+'"]'),box=document.querySelector('[data-dispatch="'+o.id+'"]');if(box)box.hidden=!done;if(live){const risk=state.level.show.includes('d')&&!done&&t>=o.d-10,late=state.level.show.includes('d')&&t>o.d;live.textContent=done?'✓ Producción terminada':late?'! Pedido retrasado':risk?'⚠ Entrega cercana':t>=o.start?'⚙ En producción':'';live.className='order-status '+(done?'done':late?'late':risk?'risk':'');}});
    document.querySelectorAll('.gantt-track').forEach(track=>{const head=track.querySelector('.playhead');head.style.display='block';head.style.left=t/Number(track.dataset.horizon)*100+'%';});
    for(const o of schedule.operations)document.querySelectorAll(`[data-operation="${o.id}"]`).forEach(el=>{el.classList.toggle('processing',t>=o.start&&t<o.end);el.classList.toggle('completed',t>=o.end);el.querySelector('.block-progress').style.width=Math.min(1,Math.max(0,(t-o.start)/o.p))*100+'%';});
    for(let m=0;m<state.level.machines;m++){const active=schedule.operations.find(o=>o.machine===m&&o.start<=t&&o.end>t),br=state.level.breaks.find(b=>(b.machine==null||b.machine===m)&&t>=b.start&&t<b.end),el=document.getElementById('machine-status-'+m);el.textContent=active?'⚙ '+active.id+' produciendo':br?'☕ '+br.label:schedule.operations.filter(o=>o.machine===m).every(o=>o.end<=t)?'✓ Completado':'◷ En espera';el.classList.toggle('working',!!active);document.querySelector('[data-live-machine="'+m+'"]')?.classList.toggle('working',!!active);}
  }
  function showResults(){
    const l=state.level,schedule=state.result.schedule,r=state.result.evaluation,o=E.OBJECTIVES[l.objective],late=schedule.operations.filter(o=>o.T>0).sort((a,b)=>b.T-a.T)[0];
    modal(`<div class="dialog-heading"><span class="tag">${r.practice?'MODO PRÁCTICA':'TURNO COMPLETADO'}</span><button class="icon-button" data-action="close" aria-label="Cerrar resultados">×</button></div><div class="result-hero">${stars(r.stars)}<h2 id="dialog-title">${r.stars===3?'¡Una producción brillante!':r.stars===2?'¡Buena programación!':'¡Turno completado!'}</h2><p>${r.practice?'Esta demostración no modifica tus récords.':'Misión '+String(l.id).padStart(2,'0')+' · '+l.title}</p><div class="result-points">${number(r.points)}<span>puntos${r.practice?' de referencia':''}</span></div></div><div class="comparison"><div><small>TU SOLUCIÓN${l.formal?' · '+o.symbol:''}</small><b>${r.playerScore} <span>${o.unit}</span></b></div><div><small>ÓPTIMO VERIFICADO</small><b>${r.optimalScore} <span>${o.unit}</span></b></div></div><div class="result-stats"><span><b>${schedule.metrics.completed}/${l.jobs.length}</b>completados</span>${l.show.includes('d')?`<span><b>${schedule.metrics.onTime}/${l.jobs.length}</b>a tiempo</span>`:''}<span><b>${(r.efficiency*100).toFixed(1)}%</b>calidad de secuencia</span></div><div class="lesson"><b>Lo que nos enseña este turno</b><p>${l.formal?l.lesson:A.naturalLessons[l.id-1]}</p><button class="text-button" data-concept="${l.objective}">Entender el concepto en la Academia →</button>${l.show.includes('d')?`<p>${late?`${late.id} tenía entrega a las ${time(late.d)} y terminó a las ${time(late.C)}. Su retraso fue de <b>${late.T} min</b>.`:'✓ Todos los pedidos llegaron a tiempo.'}</p>`:''}</div><div class="result-jobs">${schedule.operations.map(job=>`<div class="result-job ${l.show.includes('d')&&job.T?'late':'on-time'}">${Art.product(job.product)}<b>${job.id}</b><span>${l.show.includes('d')&&job.T?'⚠ +'+job.T+' min':'✓ Listo'}</span></div>`).join('')}</div><div class="new-concepts"><b>📘 Conexión con la Academia</b><p>${A.entries.filter(e=>e.unlockedAt===l.id).map(e=>`<button data-concept="${e.id}">${e.simpleName} ↗</button>`).join('')||'Sigue explorando los conceptos de este turno.'}</p></div>${l.id===MAX&&!r.practice?`<section class="graduation">${Art.medal()}<div><p class="eyebrow">🎓 JEFE DE PRODUCCIÓN</p><h3>Maestro de la Secuenciación</h3><p>Has completado todos los desafíos de La Vía Láctea. Ahora sabes conectar tus decisiones con el lenguaje de producción.</p></div></section>`:''}<details class="score-detail"><summary>Ver métricas académicas y desglose de puntos</summary><p>ΣCj: ${schedule.metrics.totalCompletion} · ΣwjCj: ${schedule.metrics.weightedCompletion} · ΣFj: ${schedule.metrics.totalFlow} · ΣLj: ${schedule.metrics.totalLateness} · ΣTj: ${schedule.metrics.totalTardiness} · ΣwjTj: ${schedule.metrics.weightedTardiness}.</p><p>Calidad = max(0, 1 − (${r.playerScore} − ${r.optimalScore}) / ${r.scale}) × 100. Escala: ${l.objective==='late-jobs'?'cantidad de pedidos':l.objective.startsWith('weighted')?'Σwjpj':'Σpj'}.</p><p>Completar: +${r.breakdown.completion} · Calidad: +${r.breakdown.efficiency} · ${l.show.includes('d')?'A tiempo':'Bono de iniciación'}: +${r.breakdown.onTime} · Sin pistas: +${r.breakdown.independent} · Óptimo: +${r.breakdown.optimal} · Pistas: ${r.breakdown.hints}.</p></details><div class="result-actions"><button class="secondary" data-action="retry">↺ Reintentar</button><button class="primary" data-action="next">${r.practice&&!state.data.results[l.id]?'Ahora me toca':l.id===MAX?'Ver mi progreso':'Siguiente misión →'}</button><button class="text-button" data-action="result-hint">Ver pista</button><button class="text-button" data-action="solution">Ver solución</button></div>${!S.available?'<p class="practice-note">No se pudo guardar en el navegador. Tu progreso sigue disponible durante esta sesión.</p>':''}`);
  }
  const simulation=new DairySimulation.ProductionSimulation({onTick:productionTick,onJobComplete:o=>DairySimulation.tone(o.T?'late':'complete',state.data.settings.sound),onComplete:()=>{
    state.running=false;state.paused=false;const schedule=currentSchedule(),benchmark=E.solveLevel(state.level),evaluation=DairyScoring.evaluateScore(state.level,schedule,benchmark,state.hints,state.revealed);
    evaluation.hintsUsed=state.hints;evaluation.allOnTime=state.level.show.includes('d')&&schedule.metrics.lateCount===0;state.result={schedule,benchmark,evaluation};S.record(state.data,state.level,evaluation);DairySimulation.tone('finish',state.data.settings.sound);render();showResults();
  }});
  function startProduction(){if(state.level.formal&&!state.examReady)return false;clearTimeout(guideTimer);if(state.guide)state.guide.playing=false;resetIdle();const schedule=currentSchedule(),validation=E.validateSchedule(state.level,schedule);if(!schedule.complete||!validation.valid){toast('Coloca todos los pedidos en las máquinas.');return false;}state.running=true;state.paused=false;render();simulation.start(schedule,state.data.settings.speed);return true;}
  function solution(){closeModal();clearTimeout(guideTimer);state.guide=null;const b=E.solveLevel(state.level);state.revealed=true;state.queues=b.queues.map(q=>[...q]);state.selected=null;state.result=null;state.hintText='Esta es una de las secuencias óptimas. Puedes simularla en modo práctica. Reintenta la misión para jugar de nuevo.';render();toast('Solución aplicada · modo práctica');}
  function navigate(view){simulation.stop();clearTimeout(guideTimer);if(state.guide){state.queues=state.guide.snapshot;state.selected=state.guide.selection;}state.guide=null;state.modalBack=null;resetIdle();state.running=false;state.paused=false;state.view=view;closeModal();render();window.scrollTo(0,0);}
  function render(){
    const focused=document.activeElement;let selector=null;
    if(focused&&app.contains(focused)){for(const key of ['data-job','data-action','data-move','data-remove','data-place-machine','data-nav']){if(focused.hasAttribute(key)){selector='['+key+'="'+CSS.escape(focused.getAttribute(key))+'"]';if(key==='data-move')selector+='[data-direction="'+focused.getAttribute('data-direction')+'"]';break;}}}
    ({home,levels:levelMap,progress,concepts,settings,game}[state.view]||home)();
    if(state.view==='game'&&state.guide){app.querySelectorAll('.orders-panel button,.queue-panel button').forEach(el=>el.disabled=true);app.querySelectorAll('[draggable]').forEach(el=>el.draggable=false);const current=state.guide.operations[state.guide.index-1];if(current)app.querySelectorAll('.guide-timeline [data-operation="'+current.id+'"]').forEach(el=>el.classList.add('guide-current'));}
    if(selector){const target=app.querySelector(selector);if(target&&!target.disabled)target.focus({preventScroll:true});}
  }
  function action(name){
    if(name==='close'){closeModal();return;}
    if(name==='return-turn'){navigate('game');return;}
    if(name==='lab-toggle'){state.lab=!state.lab;render();return;}
    if(name==='exam-check'){if(state.examAnswers.some(a=>a==null))return;state.examFeedback=A.grade(state.examAnswers);render();return;}
    if(name==='exam-retry'){state.examAnswers=[null,null,null];state.examFeedback=null;render();return;}
    if(name==='exam-continue'){if(!state.examFeedback)return;state.examReady=true;render();window.scrollTo(0,0);return;}
    if(name==='sound'){state.data.settings.sound=!state.data.settings.sound;S.save(state.data);const button=app.querySelector('[data-action="sound"]');button.textContent=state.data.settings.sound?'♫':'♩';button.setAttribute('aria-label',state.data.settings.sound?'Silenciar':'Activar sonido');toast(state.data.settings.sound?'Sonido activado':'Sonido silenciado');return;}
    if(name==='reset-dialog'){modal('<h2 id="dialog-title">¿Empezar una nueva campaña?</h2><p class="dialog-intro">Se borrarán tus estrellas, puntos y récords de este navegador.</p><div class="result-actions"><button class="secondary" data-action="close">Conservar progreso</button><button class="primary" data-action="reset">Sí, reiniciar campaña</button></div>');return;}
    if(name==='reset'){state.data=S.defaults();S.save(state.data);navigate('home');toast('Nueva campaña preparada.');return;}
    if(!state.level)return;
    if(name==='guide-start'){beginGuide();return;}
    if(name==='guide-next'){clearTimeout(guideTimer);state.guide.playing=false;guideStep(1);return;}
    if(name==='guide-back'){clearTimeout(guideTimer);state.guide.playing=false;guideStep(-1);return;}
    if(name==='guide-play'){playGuide();return;}
    if(name==='guide-restore'){restoreGuide();return;}
    if(name==='dismiss-help'){resetIdle();return;}
    if(name==='clear'&&!state.running&&!state.guide){state.queues=state.queues.map(()=>[]);state.selected=null;state.result=null;render();}
    if(name==='hint')hint();
    if(name==='start')startProduction();
    if(name==='pause'){state.paused=!state.paused;if(state.paused)simulation.pause();else simulation.resume();const b=app.querySelector('[data-action="pause"]');b.textContent=state.paused?'▶ Reanudar':'Ⅱ Pausar';}
    if(name==='finish')simulation.finish();
    if(name==='cancel-simulation'){simulation.stop();state.running=false;state.paused=false;render();}
    if(name==='retry'){closeModal();startLevel(state.level.id);}
    if(name==='result-hint'){closeModal();hint();}
    if(name==='solution')solution();
    if(name==='next'){closeModal();if(state.revealed&&!state.data.results[state.level.id]){startLevel(state.level.id);return;}if(state.level.id===MAX)navigate('progress');else startLevel(state.level.id+1);}
  }
  document.addEventListener('click',event=>{
    const el=event.target.closest('button,a');if(!el||el.disabled)return;
    if(el.dataset.concept){openConcept(el.dataset.concept);return;}
    if(el.dataset.category){state.academyCategory=el.dataset.category;render();return;}
    if(el.dataset.example!=null){state.example=Number(el.dataset.example);render();return;}
    if(el.dataset.nav){event.preventDefault();navigate(el.dataset.nav);return;}
    if(el.dataset.level){startLevel(el.dataset.level);return;}
    if(el.dataset.world){navigate('levels');document.getElementById('world-'+el.dataset.world)?.scrollIntoView({behavior:state.data.settings.reducedMotion?'instant':'smooth',block:'start'});return;}
    if(el.dataset.action){action(el.dataset.action);return;}
    if(el.dataset.job&&!state.running&&!state.guide){state.selected=state.selected===el.dataset.job?null:el.dataset.job;render();toast(state.selected?`${state.selected} seleccionado. Elige una posición en la cola.`:'Selección cancelada.');return;}
    if(el.dataset.placeMachine!=null){if(!state.selected)toast('Primero selecciona una tarjeta de pedido.');else moveJob(state.selected,Number(el.dataset.placeMachine),Number(el.dataset.placeIndex));return;}
    if(el.dataset.remove){removeJob(el.dataset.remove);return;}
    if(el.dataset.move&&!state.running&&!state.guide){resetIdle();const m=state.queues.findIndex(q=>q.includes(el.dataset.move)),i=state.queues[m].indexOf(el.dataset.move),next=i+Number(el.dataset.direction);if(next>=0&&next<state.queues[m].length){[state.queues[m][i],state.queues[m][next]]=[state.queues[m][next],state.queues[m][i]];state.result=null;render();}return;}
    if(el.dataset.inspect)inspectJob(el.dataset.inspect);
  });
  document.addEventListener('change',event=>{if(event.target.dataset.question!=null){state.examAnswers[Number(event.target.dataset.question)]=Number(event.target.value);const check=app.querySelector('[data-action="exam-check"]');if(check)check.disabled=state.examAnswers.some(a=>a==null);return;}const key=event.target.dataset.setting;if(!key)return;state.data.settings[key]=key==='speed'?Number(event.target.value):event.target.checked;S.save(state.data);simulation.speed=state.data.settings.speed;document.body.classList.toggle('reduce-motion',state.data.settings.reducedMotion);});
  DairyDragDrop.attach({onDrop:moveJob,isLocked:()=>state.running||!!state.guide||state.view!=='game'});
  document.addEventListener('toggle',event=>{if(event.target.matches?.('.quick-instructions')&&event.target.isConnected)state.instructionsOpen=event.target.open;},true);
  document.addEventListener('keydown',event=>{if(event.target.matches?.('[data-category]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const ids=A.categories.map(c=>c.id),current=ids.indexOf(state.academyCategory),next=event.key==='Home'?0:event.key==='End'?ids.length-1:(current+(event.key==='ArrowRight'?1:-1)+ids.length)%ids.length;state.academyCategory=ids[next];render();document.querySelector('[data-category="'+ids[next]+'"]')?.focus();return;}if(event.key==='Escape'&&state.selected){state.selected=null;render();}});
  document.getElementById('modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
  // Optional structured access mirrors the same UI actions; browsers without WebMCP ignore it.
  if(document.modelContext?.registerTool){
    const lifecycle=new AbortController();
    const tools=[
      {name:'read_factory_state',description:'Read current visible mission, machine queues and calculated metrics.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({view:state.view,level:state.level?.id,queues:state.queues,schedule:state.level?currentSchedule():null,progress:S.totals(state.data)})},
      {name:'start_factory_mission',description:'Open an unlocked campaign mission with empty machine queues.',inputSchema:{type:'object',properties:{id:{type:'integer',minimum:1,maximum:MAX}},required:['id'],additionalProperties:false},execute:input=>{if(!Number.isInteger(input?.id)||!startLevel(input.id))throw new Error('Misión inválida o bloqueada.');return {level:state.level.id};}},
      {name:'stage_factory_queues',description:'Replace the full draft assignment and order for the open mission; does not start production.',inputSchema:{type:'object',properties:{queues:{type:'array',items:{type:'array',items:{type:'string'}}}},required:['queues'],additionalProperties:false},execute:input=>{if(!state.level||state.view!=='game'||state.running||state.guide||(state.level.formal&&!state.examReady))throw new Error('Abre una misión y detén la producción.');const schedule=E.calculateSchedule(state.level,input?.queues);resetIdle();state.queues=input.queues.map(q=>[...q]);state.selected=null;state.result=null;render();return {objective:schedule.objective,complete:schedule.complete};}}
    ];
    tools.forEach(tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch(e){}});
    window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  }
  render();
})();
